import { existsSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import sharp from 'sharp';
import { describe, expect, it } from 'vitest';

import manifest from '../src/data/hero-layers.json';

/**
 * The hero's real-UI layers are generated by scripts/build-hero-layers.ts and committed.
 * These checks catch a stale manifest, a missing or resized image, or geometry that would
 * slide the transcript outside its window.
 */
const PUBLIC_DIR = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../public');

interface Layer {
  files: { dark: string; light: string };
  width?: number;
  height?: number;
}

const layers: [string, Layer][] = [
  ...Object.entries(manifest.windows).flatMap(([name, win]): [string, Layer][] => [
    [name, win.base],
    [`${name}-strip`, win.strip],
    [`${name}-stop`, win.stop],
  ]),
  ...Object.entries(manifest.crops),
];

describe('hero layer manifest', () => {
  it.each(layers)('%s exists in both themes at the recorded size', async (_name, layer) => {
    for (const file of [layer.files.dark, layer.files.light]) {
      expect(file).toMatch(/^\/images\/hero\/[\w-]+\.webp$/);
      const onDisk = path.join(PUBLIC_DIR, file);
      expect(existsSync(onDisk), file).toBe(true);
      if (layer.width && layer.height) {
        const { width, height } = await sharp(onDisk).metadata();
        expect({ width, height }, file).toEqual({ width: layer.width, height: layer.height });
      }
    }
    expect(layer.files.light).toBe(layer.files.dark.replace(/\.webp$/, '-light.webp'));
  });

  it.each(Object.entries(manifest.windows))('%s keeps its transcript and stop button inside the window', (_name, win) => {
    const { view, stopBox, strip } = win;
    for (const value of [view.left, view.top, view.width, view.height, stopBox.left, stopBox.top, stopBox.width]) {
      expect(value).toBeGreaterThanOrEqual(0);
      expect(value).toBeLessThanOrEqual(100);
    }
    expect(view.left + view.width).toBeLessThanOrEqual(100);
    expect(view.top + view.height).toBeLessThanOrEqual(100);
    expect(stopBox.left + stopBox.width).toBeLessThanOrEqual(100);

    // The strip and the window share one scale, so the strip spans exactly the view's width.
    expect(strip.width / win.base.width).toBeCloseTo(view.width / 100, 2);

    // Each beat raises the transcript further, ending on the real frame, and the band above
    // the transcript always covers the gap it leaves (offset never above 0).
    expect(strip.offsets.length).toBeGreaterThan(1);
    for (let i = 1; i < strip.offsets.length; i++) {
      expect(strip.offsets[i] ?? 0).toBeLessThan(strip.offsets[i - 1] ?? 0);
    }
    expect(Math.max(...strip.offsets)).toBeLessThanOrEqual(0);
    expect(strip.maskStop).toBeGreaterThan(0);
    expect(strip.maskStop).toBeLessThan(25);
  });
});
